// [slug, name, one-line definition, category, written in this locale (1) or English fallback (0)], sorted by name.
export const GLOSSARY_INDEX = Object.freeze({"locale":"ko","terms":[["two-factor-authentication","2단계 인증(2FA, OTP)","2단계 인증(2FA)은 비밀번호 외에 OTP 앱 코드나 보안 키 같은 두 번째 수단을 추가로 요구해 계정 탈취를 어렵게 만드는 보안 기능입니다.","wallets-security",1],["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다.","basics",1],["instant-convert","간편 전환(Convert)","간편 전환은 호가창에서 주문을 내지 않고, 거래소가 제시한 견적 가격으로 한 코인을 다른 코인으로 즉시 바꿔 주는 기능입니다.","exchange-features",1],["liquidation","강제청산(Liquidation)","강제청산은 레버리지 포지션의 손실로 증거금이 유지 증거금 아래로 떨어졌을 때 거래소가 더 큰 손실을 막기 위해 포지션을 강제로 정리하는 것입니다.","derivatives",1],["private-key","개인 키(Private Key)","개인 키는 블록체인 주소의 자산을 사용할 수 있게 해 주는 비밀 숫자로, 이 키로 거래에 서명해야 송금이 이뤄집니다.","wallets-security",1],["trading-pair","거래 페어(Trading Pair)","거래 페어는 어떤 코인을 어떤 자산으로 사고파는지를 나타내는 조합으로, BTC/USDT는 BTC를 USDT로 거래한다는 뜻입니다.","trading",1],["trading-volume","거래량(Trading Volume)","거래량은 일정 기간 동안 실제로 체결된 코인의 수량 또는 금액을 말하며, 보통 24시간 기준으로 시장의 관심과 활발함을 보여 줍니다.","trading",1],["crypto-earn","거래소 예치 상품(Crypto Earn)","거래소 예치 상품은 거래소에 코인을 맡기면 정해진 기간이나 자유 입출금 조건으로 이자 성격의 보상을 주는 상품군을 말합니다.","exchange-features",1],["exchange-netflow","거래소 유입·유출(넷플로우)","거래소 유입·유출은 일정 기간 거래소 지갑으로 들어오고 나간 코인 양을 집계한 온체인 지표이며, 유입에서 유출을 뺀 값을 넷플로우라고 합니다.","onchain",1],["governance-token","거버넌스 토큰(Governance Token)","거버넌스 토큰은 보유량에 비례해 프로토콜이나 DAO의 주요 결정에 투표할 권리를 주는 토큰입니다.","defi",1],["validator","검증자(Validator)","검증자는 지분증명 블록체인에서 코인을 예치하고 노드를 운영하며 새 블록을 제안하고 다른 블록을 검증해 보상을 받는 참여자입니다.","basics",1],["isolated-margin","격리 마진(Isolated Margin)","격리 마진은 포지션마다 증거금을 따로 배정해, 그 포지션이 청산되더라도 배정한 증거금만 잃고 계좌의 나머지 잔고는 영향을 받지 않는 마진 방식입니다.","derivatives",1],["whale","고래(Whale)","고래는 특정 코인을 매우 많이 보유하거나 큰 금액을 한 번에 거래해 시장 가격에 영향을 줄 수 있는 개인이나 기관을 부르는 말입니다.","trading",1],["public-key","공개 키(Public Key)","공개 키는 개인 키에서 수학적으로 계산되는 값으로, 다른 사람이 내 서명이 진짜인지 확인할 때 쓰이며 지갑 주소를 만드는 바탕이 됩니다.","wallets-security",1],["short-selling","공매도(Short Selling)","공매도는 보유하지 않은 자산을 빌리거나 계약으로 먼저 팔고, 가격이 내려간 뒤 더 싸게 사서 갚아 그 차이만큼 이익을 얻는 거래 방식입니다.","derivatives",1],["fear-and-greed-index","공포 탐욕 지수(Fear and Greed Index)","공포 탐욕 지수는 가격 변동성, 거래량, 소셜 미디어 반응 같은 데이터를 0에서 100 사이 점수로 묶어 시장 심리를 보여 주는 지표입니다.","onchain",1],["cross-margin","교차 마진(Cross Margin)","교차 마진은 계좌의 사용 가능한 잔고 전체를 여러 포지션이 함께 증거금으로 쓰는 방식으로, 청산가는 멀어지지만 한 번 청산되면 계좌 잔고 대부분을 잃을 수 있습니다.","derivatives",1],["grid-trading-bot","그리드 트레이딩 봇","그리드 트레이딩 봇은 정해진 가격 범위를 여러 칸으로 나눠 낮은 칸에서 사고 높은 칸에서 파는 지정가 주문을 자동으로 반복하는 매매 도구입니다.","exchange-features",1],["tokenized-gold","금 토큰(Tokenized gold)","금 토큰은 금고에 보관된 실물 금을 기초로 발행되어, 토큰 1개가 정해진 무게의 금 소유권이나 청구권을 나타내는 블록체인 자산입니다.","tokenized-assets",1],["node","노드(Node)","노드는 블록체인 소프트웨어를 실행하며 거래와 블록을 검증하고 다른 컴퓨터에 전달하는 네트워크 참여 컴퓨터입니다.","onchain",1],["no-kyc-exchange","노KYC 거래소","노KYC 거래소는 신분증 인증 없이 가입하거나 일정 한도까지 거래·출금할 수 있도록 운영되는 암호화폐 거래 서비스입니다.","regulation",1],["pig-butchering-scam","돼지 도살 사기(Pig Butchering Scam)","돼지 도살 사기는 SNS나 메신저로 친분이나 연애 감정을 쌓은 뒤 가짜 투자 플랫폼으로 유도해 점점 더 큰 돈을 넣게 하고 결국 출금을 막는 장기 사기입니다.","wallets-security",1],["defi-lending","디파이 대출(DeFi Lending)","디파이 대출은 에이브(Aave)나 컴파운드 같은 프로토콜에 코인을 예치해 이자를 받거나, 담보를 맡기고 다른 코인을 빌리는 스마트 컨트랙트 기반 대출 서비스입니다.","defi",1],["defi","디파이(DeFi, 탈중앙화 금융)","디파이(DeFi)는 은행이나 거래소 같은 중개자 없이 블록체인 위 스마트 컨트랙트로 거래, 대출, 예치 같은 금융 서비스를 제공하는 생태계입니다.","defi",1],["depeg","디페깅(Depeg)","디페깅은 1달러 같은 기준 가치에 고정(페깅)되도록 설계된 스테이블코인이나 자산의 가격이 그 기준에서 눈에 띄게 벗어나는 현상입니다.","stablecoins",1],["wrapped-token","래핑 토큰(Wrapped Token)","래핑 토큰은 다른 자산을 일정 비율, 보통 1대1로 담보로 맡기고 다른 블록체인이나 다른 표준에서 쓸 수 있게 발행한 대체 토큰입니다.","defi",1],["rug-pull","러그풀(Rug Pull)","러그풀은 프로젝트 개발자나 운영자가 투자자의 돈이 모이면 유동성을 빼 가거나 토큰을 대량 매도하고 사라지는 사기 행위입니다.","wallets-security",1],["launchpad","런치패드(Launchpad)","런치패드는 거래소나 플랫폼이 신규 프로젝트의 토큰을 상장 전에 정해진 가격으로 사용자에게 판매하는 토큰 세일 서비스입니다.","exchange-features",1],["launchpool","런치풀(Launchpool)","런치풀은 거래소가 신규 토큰을 상장하기 전후에 사용자가 BNB나 USDT 등 지정 자산을 맡겨 두면 그 비율에 따라 새 토큰을 나눠 주는 이벤트입니다.","exchange-features",1],["leverage","레버리지(Leverage)","레버리지는 맡긴 증거금보다 몇 배 큰 규모의 포지션을 거래하는 것으로, 수익과 손실이 모두 그 배수만큼 커지고 강제청산 위험도 함께 커집니다.","derivatives",1],["layer-1","레이어1(Layer 1, L1)","레이어1(L1)은 거래의 처리와 최종 확정을 스스로 담당하는 기본 블록체인으로, 비트코인, 이더리움, 솔라나처럼 자체 합의 방식과 네이티브 코인을 가집니다.","basics",1],["layer-2","레이어2(Layer 2, L2)","레이어2(L2)는 레이어1 블록체인 위에서 거래를 더 빠르고 저렴하게 처리한 뒤, 그 결과를 레이어1에 기록해 보안을 이어받는 확장 네트워크입니다.","basics",1],["referral-code","레퍼럴 코드(수수료 페이백)","레퍼럴 코드는 거래소 가입 시 입력하는 추천 코드로, 연결된 계정의 거래 수수료 일부를 사용자에게 할인이나 페이백 형태로 돌려주는 데 쓰입니다.","exchange-features",1],["long-and-short","롱과 숏(Long and Short)","롱은 가격이 오를 것으로 보고 매수해 상승 시 이익을 얻는 포지션이고, 숏은 가격이 내릴 것으로 보고 매도해 하락 시 이익을 얻는 포지션입니다.","derivatives",1],["long-short-ratio","롱숏 비율(Long/Short Ratio)","롱숏 비율은 특정 거래소나 시장에서 롱 포지션을 가진 계정 또는 롱 포지션 규모가 숏에 비해 얼마나 많은지를 나타내는 투자 심리 지표입니다.","derivatives",1],["reduce-only-order","리듀스 온리 주문(Reduce-Only)","리듀스 온리 주문은 기존 포지션을 줄이거나 닫는 데만 쓰이고, 포지션을 늘리거나 반대 방향 포지션을 새로 열지 않도록 제한된 주문 옵션입니다.","derivatives",1],["restaking","리스테이킹(Restaking)","리스테이킹은 이미 스테이킹한 ETH나 리퀴드 스테이킹 토큰을 다른 서비스의 보안에도 다시 담보로 제공해 추가 보상을 받는 구조입니다.","defi",1],["liquid-staking","리퀴드 스테이킹(Liquid Staking)","리퀴드 스테이킹은 코인을 스테이킹하면서 그 지분을 나타내는 토큰(LST)을 받아, 보상을 받는 동안에도 그 토큰을 거래하거나 디파이에 활용할 수 있게 하는 방식입니다.","defi",1],["margin-trading","마진 거래(Margin Trading)","마진 거래는 계좌의 자산을 증거금으로 맡기고 거래소에서 자금을 빌려 보유 자금보다 큰 규모로 사거나, 코인을 빌려 팔아 하락에 베팅하는 거래입니다.","derivatives",1],["margin-call","마진콜(Margin Call)","마진콜은 손실로 증거금이 줄어 청산 기준에 가까워졌을 때 증거금을 추가하거나 포지션을 줄이라고 알리는 경고입니다.","derivatives",1],["market-maker","마켓메이커(Market Maker)","마켓메이커는 매수 호가와 매도 호가를 동시에 꾸준히 걸어 두어 다른 사람이 언제든 거래할 수 있도록 유동성을 공급하는 참여자입니다.","trading",1],["mark-price","마크 가격(Mark Price)","마크 가격은 선물 거래소가 평가 손익과 강제청산을 계산할 때 쓰는 기준 가격으로, 여러 현물 거래소의 지수 가격을 바탕으로 만들어 순간적인 가격 조작의 영향을 줄입니다.","derivatives",1],["delivery-futures","만기 선물(분기 선물, Delivery Futures)","만기 선물은 정해진 만기일에 계약이 종료되고 그 시점 가격으로 정산되는 선물 계약으로, 흔히 분기마다 만기가 돌아오는 분기 선물 형태로 거래됩니다.","derivatives",1],["multisig-wallet","멀티시그 지갑(Multisig Wallet)","멀티시그 지갑은 여러 개의 개인 키 가운데 정해진 수 이상이 함께 서명해야 송금할 수 있는 지갑으로, 키 하나가 유출돼도 자산을 옮길 수 없게 합니다.","wallets-security",1],["memo-tag","메모·데스티네이션 태그(Memo/Tag)","메모(태그)는 거래소처럼 여러 사용자가 하나의 입금 주소를 함께 쓸 때 어느 계정의 입금인지 구분하기 위해 주소와 함께 입력하는 번호나 문자입니다.","wallets-security",1],["maker-taker-fees","메이커·테이커 수수료(Maker/Taker Fee)","메이커·테이커 수수료는 호가창에 새 주문을 걸어 유동성을 공급한 쪽(메이커)과 이미 걸린 주문을 즉시 체결한 쪽(테이커)에 서로 다르게 매기는 거래 수수료입니다.","trading",1],["mempool","멤풀(Mempool)","멤풀은 블록에 아직 포함되지 않은 거래들이 노드마다 대기하는 공간으로, 채굴자나 검증자가 여기서 거래를 골라 블록을 만듭니다.","onchain",1],["demo-trading","모의 거래(데모 트레이딩)","모의 거래는 실제 돈 대신 거래소가 지급하는 가상 자금으로 실제와 비슷한 시장 환경에서 주문과 포지션 관리를 연습하는 기능입니다.","exchange-features",1],["perp-dex","무기한 선물 DEX(Perp DEX)","무기한 선물 DEX(Perp DEX)는 개인 지갑을 연결해 블록체인 위에서 무기한 선물을 레버리지로 거래하는 탈중앙화 거래소입니다.","defi",1],["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다.","derivatives",1],["open-interest","미결제약정(Open Interest)","미결제약정(OI)은 아직 청산되거나 정산되지 않고 시장에 남아 있는 선물·옵션 계약의 총량으로, 파생상품 시장에 얼마나 많은 자금이 걸려 있는지 보여 줍니다.","derivatives",1],["unrealized-pnl","미실현 손익(Unrealized PnL)","미실현 손익은 아직 닫지 않은 포지션을 현재 가격으로 평가했을 때의 이익이나 손실로, 포지션을 청산해야 실현 손익으로 확정됩니다.","derivatives",1],["memecoin","밈코인(Memecoin)","밈코인은 인터넷 밈이나 유머, 커뮤니티 문화를 바탕으로 만들어진 암호화폐로, 뚜렷한 기능보다 관심과 화제성이 가격을 크게 좌우하는 코인입니다.","basics",1],["fiat-on-ramp","법정화폐 온램프(Fiat on-ramp)","법정화폐 온램프는 원화나 달러 같은 법정화폐를 암호화폐로 바꿔 시장에 처음 들어오는 경로로, 거래소 입금, 카드 결제, P2P 거래 등이 있습니다.","regulation",1],["futures-basis","베이시스(Futures Basis)","베이시스는 선물 가격과 현물 가격의 차이로, 선물이 현물보다 비싸면 플러스(콘탱고), 싸면 마이너스(백워데이션)라고 부릅니다.","derivatives",1],["volatility","변동성(Volatility)","변동성은 일정 기간 동안 가격이 얼마나 크고 빠르게 오르내리는지를 나타내는 정도로, 변동성이 클수록 같은 기간에 가격이 더 크게 움직입니다.","basics",1],["insurance-fund","보험 기금(Insurance Fund)","보험 기금은 강제청산된 포지션이 파산 가격보다 나쁜 가격에 정리될 때 생기는 손실을 메우기 위해 선물 거래소가 별도로 쌓아 두는 자금입니다.","derivatives",1],["block-explorer","블록 익스플로러(Block explorer)","블록 익스플로러는 블록체인의 거래, 주소 잔고, 블록 정보를 누구나 검색해 볼 수 있게 보여 주는 웹 서비스입니다.","onchain",1],["block-confirmations","블록 확인 수(Confirmations)","블록 확인 수는 거래가 담긴 블록 뒤에 새 블록이 몇 개 더 쌓였는지를 뜻하며, 숫자가 클수록 거래가 뒤집힐 가능성이 낮아집니다.","wallets-security",1],["oracle","블록체인 오라클(Oracle)","블록체인 오라클은 코인 가격, 환율, 경기 결과처럼 블록체인 밖에 있는 데이터를 스마트 컨트랙트가 읽을 수 있도록 체인 위로 전달하는 시스템입니다.","defi",1],["blockchain","블록체인(Blockchain)","블록체인은 거래 기록을 블록 단위로 묶어 시간 순서대로 연결하고, 여러 컴퓨터가 같은 사본을 나눠 보관하는 분산 장부입니다.","basics",1],["non-custodial-wallet","비수탁형 지갑(Non-custodial Wallet, 개인 지갑)","비수탁형 지갑은 거래소 같은 제3자가 아니라 사용자 본인이 개인 키와 시드 문구를 직접 보관하고 관리하는 암호화폐 지갑입니다.","wallets-security",1],["impermanent-loss","비영구적 손실(Impermanent Loss)","비영구적 손실은 유동성 풀에 넣은 두 토큰의 가격 비율이 변했을 때, 그냥 지갑에 들고 있었던 경우보다 풀에서 꺼낸 자산 가치가 줄어드는 현상입니다.","defi",1],["bitcoin-halving","비트코인 반감기(Halving)","비트코인 반감기는 21만 블록(약 4년)마다 채굴 보상이 절반으로 줄어드는 프로토콜 규칙으로, 새 비트코인의 발행 속도를 낮춥니다.","basics",1],["spot-bitcoin-etf","비트코인 현물 ETF","비트코인 현물 ETF는 실제 비트코인을 보유하고 그 가격을 따라가도록 설계된 상장지수펀드로, 증권 계좌에서 주식처럼 사고팔 수 있습니다.","regulation",1],["bitcoin","비트코인(Bitcoin, BTC)","비트코인(BTC)은 2009년 운영을 시작한 최초의 암호화폐로, 작업증명 블록체인 위에서 중앙 관리자 없이 발행되며 총발행량이 2,100만 개로 정해져 있습니다.","basics",1],["satoshi","사토시(Satoshi, sats)","사토시는 비트코인의 최소 단위로, 1 BTC는 1억(100,000,000) 사토시이며 1 사토시는 0.00000001 BTC입니다.","basics",1],["bull-market","상승장(Bull Market, 불장)","상승장은 가격이 비교적 긴 기간 동안 전반적으로 오르고 투자 심리가 낙관적인 시장 국면으로, 코인 커뮤니티에서는 흔히 불장이라고 부릅니다.","basics",1],["delisting","상장폐지(Delisting)","상장폐지는 거래소가 특정 코인의 거래 페어를 닫고 일정 기간 뒤 입출금 지원까지 종료하는 것으로, 국내 거래소에서는 거래 지원 종료라고도 부릅니다.","exchange-features",1],["sub-account","서브 계정(Sub-account)","서브 계정은 하나의 메인 계정 아래에 만드는 별도 거래 계정으로, 자금과 포지션, API 키를 전략별로 분리해 관리할 수 있게 해 줍니다.","exchange-features",1],["futures-contract","선물 계약(Futures Contract)","선물 계약은 특정 자산을 미리 정한 가격으로 사고팔기로 약속하는 파생상품으로, 코인을 직접 보유하지 않고도 가격 상승이나 하락에 베팅할 수 있습니다.","derivatives",1],["risk-reward-ratio","손익비(Risk-Reward Ratio)","손익비는 한 번의 거래에서 감수하는 손실 폭(진입가와 손절가의 차이)과 기대하는 수익 폭(진입가와 익절가의 차이)을 비교한 비율입니다.","trading",1],["stop-loss","손절 주문(Stop-Loss)","손절 주문(스탑로스)은 가격이 미리 정한 수준까지 불리하게 움직이면 자동으로 포지션을 정리해 손실을 제한하는 주문입니다.","trading",1],["short-squeeze","숏 스퀴즈(Short Squeeze)","숏 스퀴즈는 숏 포지션이 많이 쌓인 상태에서 가격이 오르자 숏 보유자들의 손절과 강제청산이 연쇄적으로 매수 주문을 만들어 가격이 급등하는 현상입니다.","derivatives",1],["custodial-wallet","수탁형 지갑(Custodial Wallet)","수탁형 지갑은 거래소나 서비스 업체가 개인 키를 대신 보관하고 관리하는 지갑으로, 이용자는 아이디와 비밀번호로 접근하지만 코인의 직접 통제권은 업체에 있습니다.","wallets-security",1],["smart-contract","스마트 컨트랙트(Smart Contract)","스마트 컨트랙트는 블록체인에 배포되어 미리 정한 조건이 충족되면 자동으로 실행되는 프로그램으로, 중개자 없이 거래와 규칙을 처리합니다.","basics",1],["stop-limit-order","스탑 리밋 주문(Stop-Limit Order)","스탑 리밋 주문은 가격이 트리거(스탑) 가격에 도달하면 미리 정한 지정가 주문이 호가창에 올라가도록 하는 조건부 주문입니다.","trading",1],["stablecoin","스테이블코인(Stablecoin)","스테이블코인은 미국 달러 같은 법정화폐나 다른 자산의 가치에 가격을 고정하도록 설계된 암호화폐로, USDT와 USDC가 대표적입니다.","stablecoins",1],["staking","스테이킹(Staking)","스테이킹은 지분증명(PoS) 블록체인에서 코인을 맡겨 네트워크 검증에 참여하거나 검증인에게 위임하고 그 대가로 보상을 받는 방법입니다.","defi",1],["bid-ask-spread","스프레드(Bid-Ask Spread)","스프레드는 호가창에서 가장 높은 매수 호가(bid)와 가장 낮은 매도 호가(ask) 사이의 가격 차이로, 즉시 사고팔 때 부담하는 숨은 거래 비용입니다.","trading",1],["slippage","슬리피지(Slippage)","슬리피지는 주문할 때 예상한 가격과 실제로 체결된 평균 가격의 차이로, 호가가 얇거나 가격이 빠르게 움직일 때 커집니다.","trading",1],["market-capitalization","시가총액(Market Cap)","시가총액은 코인의 현재 가격에 유통 공급량을 곱한 값으로, 시장이 그 자산 전체를 얼마로 평가하고 있는지 보여 주는 지표입니다.","basics",1],["seed-phrase","시드 문구(Seed Phrase, 복구 문구)","시드 문구는 지갑을 만들 때 생성되는 12개 또는 24개의 영어 단어 목록으로, 이것만 있으면 지갑의 모든 개인 키와 자산을 복구할 수 있는 마스터 키입니다.","wallets-security",1],["market-order","시장가 주문(Market Order)","시장가 주문은 가격을 지정하지 않고 현재 호가창에 있는 가장 유리한 가격부터 즉시 체결하는 주문으로, 빠른 체결을 대가로 가격을 보장받지 못합니다.","trading",1],["real-world-assets","실물자산 토큰화(RWA)","RWA는 국채, 주식, 금, 부동산, 대출 채권처럼 블록체인 밖에 존재하는 실물·금융 자산의 소유권이나 수익권을 토큰으로 발행한 것을 말합니다.","tokenized-assets",1],["algorithmic-stablecoin","알고리즘 스테이블코인","알고리즘 스테이블코인은 충분한 준비금 없이 코드와 시장 인센티브로 공급량을 늘리고 줄여 1달러 가치를 유지하려는 스테이블코인입니다.","stablecoins",1],["altcoin","알트코인(Altcoin)","알트코인은 비트코인을 제외한 나머지 암호화폐를 통틀어 부르는 말로, 이더리움, 솔라나, XRP 같은 대형 코인부터 소형 토큰까지 모두 포함합니다.","basics",1],["crypto-backed-stablecoin","암호화폐 담보 스테이블코인","암호화폐 담보 스테이블코인은 달러 예금 대신 ETH 같은 암호화폐를 담보로 맡기고, 담보 가치보다 적은 양만 발행하는 스테이블코인입니다.","stablecoins",1],["crypto-wallet","암호화폐 지갑(Crypto Wallet)","암호화폐 지갑은 블록체인에 있는 코인을 보내고 받을 수 있도록 개인 키를 보관하고 관리하는 도구로, 코인 자체가 아니라 코인을 움직일 권한을 담고 있습니다.","wallets-security",1],["cryptocurrency","암호화폐(Cryptocurrency)","암호화폐는 블록체인 위에서 암호 기술로 소유권과 거래를 증명하는 디지털 자산으로, 중앙은행이 아닌 네트워크 규칙에 따라 발행되고 전송됩니다.","basics",1],["airdrop","에어드랍(Airdrop)","에어드랍은 프로젝트가 홍보, 커뮤니티 보상, 탈중앙화 분배를 위해 특정 조건을 만족한 지갑에 토큰을 무료로 나눠 주는 것입니다.","basics",1],["all-time-high","역대 최고가(ATH)","역대 최고가(ATH)는 어떤 자산이 거래를 시작한 이후 기록한 가장 높은 가격으로, 코인 커뮤니티에서는 전고점이나 신고가라는 표현도 함께 씁니다.","basics",1],["on-chain-analysis","온체인 분석","온체인 분석은 블록체인에 공개 기록된 거래, 주소, 잔고 데이터를 읽어 자금 흐름과 네트워크 사용 현황을 파악하는 분석 방법입니다.","onchain",1],["fully-diluted-valuation","완전 희석 가치(FDV)","완전 희석 가치(FDV)는 코인의 현재 가격에 앞으로 발행될 물량까지 포함한 최대 또는 총 공급량을 곱한 값으로, 모든 토큰이 풀렸을 때의 평가 규모를 보여 줍니다.","basics",1],["liquidity-pool","유동성 풀(Liquidity Pool)","유동성 풀은 DEX에서 거래가 가능하도록 두 가지 이상의 토큰을 스마트 컨트랙트에 함께 예치해 둔 자금 저장소로, 공급자는 거래 수수료를 나눠 받습니다.","defi",1],["liquidity","유동성(Liquidity)","유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다.","trading",1],["maintenance-margin","유지 증거금(Maintenance Margin)","유지 증거금은 레버리지 포지션을 계속 유지하기 위해 계좌에 남아 있어야 하는 최소 증거금으로, 증거금이 이 수준 아래로 떨어지면 강제청산이 시작됩니다.","derivatives",1],["circulating-supply","유통량(Circulating Supply)","유통량은 현재 시장에서 실제로 거래될 수 있는 코인의 수량으로, 잠겨 있거나 아직 발행되지 않은 물량은 제외합니다.","basics",1],["ethereum","이더리움(Ethereum, ETH)","이더리움(ETH)은 스마트 컨트랙트를 실행할 수 있는 블록체인 플랫폼이며, ETH는 그 네트워크에서 가스비를 내고 스테이킹에 쓰이는 기본 코인입니다.","basics",1],["dual-investment","이중 투자(Dual investment)","이중 투자는 목표 가격과 만기를 정해 코인이나 스테이블코인을 맡기면, 만기 시 가격에 따라 원래 자산 또는 다른 자산으로 원금과 보상을 돌려받는 구조화 상품입니다.","exchange-features",1],["take-profit","익절 주문(Take-Profit)","익절 주문(테이크프로핏)은 가격이 미리 정한 목표 수준에 도달하면 자동으로 포지션을 정리해 이익을 확정하는 주문입니다.","trading",1],["yield-farming","일드 파밍(Yield Farming)","일드 파밍은 디파이 프로토콜에 자산을 예치하거나 유동성을 공급하고 그 대가로 이자, 수수료, 보상 토큰을 받아 수익을 쌓는 전략입니다.","defi",1],["blockchain-network","입금 네트워크(체인 선택)","입금 네트워크는 같은 코인을 어떤 블록체인으로 보낼지 고르는 설정으로, 보내는 쪽과 받는 쪽의 네트워크가 반드시 같아야 합니다.","wallets-security",1],["auto-deleveraging","자동 디레버리징(ADL)","자동 디레버리징(ADL)은 청산된 포지션의 손실을 보험 기금으로도 메울 수 없을 때, 반대편에서 이익을 내고 있는 포지션 일부를 강제로 줄여 손실을 처리하는 거래소의 최후 장치입니다.","derivatives",1],["amm","자동화 마켓 메이커(AMM)","자동화 마켓 메이커(AMM)는 매수자와 매도자를 호가창에서 맞추는 대신 유동성 풀에 쌓인 두 토큰의 비율과 수학 공식으로 가격을 자동으로 정하는 거래 방식입니다.","defi",1],["wash-trading","자전거래(Wash Trading)","자전거래는 같은 사람이나 한편인 계정끼리 사고팔기를 반복해 실제 수요 없이 거래량과 가격 움직임을 부풀리는 행위입니다.","trading",1],["proof-of-work","작업증명(Proof of Work, PoW)","작업증명(PoW)은 채굴자가 대량의 연산으로 특정 조건을 만족하는 해시값을 먼저 찾아내야 블록을 추가할 수 있게 하는 블록체인 합의 방식입니다.","basics",1],["dollar-cost-averaging","적립식 분할 매수(DCA)","적립식 분할 매수(DCA)는 가격과 상관없이 정해진 금액을 일정한 간격으로 꾸준히 매수해 평균 매수 단가를 분산시키는 방법입니다.","trading",1],["time-in-force","주문 유효 조건(Time in Force: GTC, IOC, FOK)","주문 유효 조건(Time in Force)은 주문이 체결되지 않았을 때 얼마나 오래 유지할지와 일부 체결을 허용할지를 정하는 설정으로, GTC, IOC, FOK가 대표적입니다.","trading",1],["address-poisoning","주소 오염 공격(Address Poisoning)","주소 오염 공격은 내 주소와 앞뒤 글자가 비슷한 가짜 주소로 소액이나 0원 거래를 보내 거래 내역에 섞어 두고, 다음 송금 때 그 주소를 잘못 복사하게 만드는 사기입니다.","wallets-security",1],["stock-perpetuals","주식 무기한 선물","주식 무기한 선물은 테슬라나 엔비디아 같은 주식의 가격을 추종하는 만기 없는 선물 계약으로, USDT 증거금과 레버리지로 롱과 숏을 거래합니다.","tokenized-assets",1],["proof-of-reserves","준비금 증명(Proof of Reserves)","준비금 증명은 거래소가 고객이 맡긴 자산만큼의 코인을 실제로 보유하고 있는지 온체인 주소와 암호학적 방식으로 보여 주는 공개 검증 절차입니다.","wallets-security",1],["centralized-exchange","중앙화 거래소(CEX)","중앙화 거래소(CEX)는 회사가 운영하며 사용자의 자산을 보관하고 주문을 자체 시스템에서 체결해 주는 암호화폐 거래소입니다.","trading",1],["wallet-address","지갑 주소(Wallet Address)","지갑 주소는 블록체인에서 코인을 받을 때 쓰는 문자열로, 은행 계좌번호처럼 다른 사람에게 알려 줘도 되는 수신용 식별자입니다.","wallets-security",1],["proof-of-stake","지분증명(Proof of Stake, PoS)","지분증명(PoS)은 코인을 담보로 예치한 검증자가 블록을 제안하고 검증할 자격을 얻는 블록체인 합의 방식으로, 채굴 장비 대신 예치한 지분이 보안의 근거가 됩니다.","basics",1],["index-price","지수 가격(Index Price)","지수 가격은 여러 주요 현물 거래소의 가격을 가중 평균해 만든 기준 가격으로, 선물의 마크 가격과 펀딩비를 계산하는 바탕이 됩니다.","derivatives",1],["geo-restrictions","지역 제한(서비스 제한 국가)","지역 제한은 거래소가 규제나 라이선스 문제로 특정 국가나 지역의 거주자에게 가입, 일부 상품, 또는 서비스 전체를 제공하지 않는 정책입니다.","regulation",1],["limit-order","지정가 주문(Limit Order)","지정가 주문은 사거나 팔 가격을 직접 정해 두고, 시장 가격이 그 가격이나 더 유리한 가격에 도달했을 때만 체결되는 주문입니다.","trading",1],["support-and-resistance","지지선과 저항선(Support and Resistance)","지지선은 매수세가 몰려 가격 하락이 자주 멈추는 가격대이고, 저항선은 매도세가 몰려 가격 상승이 자주 막히는 가격대입니다.","trading",1],["arbitrage","차익거래(Arbitrage)","차익거래는 같은 자산이 거래소나 시장에 따라 다른 가격에 거래될 때 싼 곳에서 사고 비싼 곳에서 팔아 가격 차이만큼 수익을 얻는 거래입니다.","trading",1],["mining","채굴(Crypto Mining)","채굴은 작업증명 블록체인에서 컴퓨터 연산으로 새 블록을 만들고 거래를 확정하는 과정으로, 채굴자는 그 대가로 블록 보상과 거래 수수료를 받습니다.","basics",1],["liquidation-price","청산가(Liquidation Price)","청산가는 마크 가격이 그 수준에 닿으면 증거금이 유지 증거금 아래로 떨어져 포지션이 강제청산되는 가격입니다.","derivatives",1],["initial-margin","초기 증거금(Initial Margin)","초기 증거금은 레버리지 포지션을 새로 열 때 담보로 맡겨야 하는 최소 금액으로, 보통 포지션 규모를 레버리지 배수로 나눈 값입니다.","derivatives",1],["last-price","최근 체결가(Last Price)","최근 체결가는 해당 거래소 시장에서 가장 마지막으로 실제 체결된 거래의 가격으로, 차트와 시세 화면에 현재가로 표시되는 값입니다.","derivatives",1],["withdrawal-fee","출금 수수료","출금 수수료는 거래소에서 코인을 외부 지갑이나 다른 거래소로 보낼 때 출금 수량에서 차감되는 비용으로, 코인과 네트워크마다 다르게 정해집니다.","exchange-features",1],["withdrawal-whitelist","출금 화이트리스트(Withdrawal Whitelist)","출금 화이트리스트는 미리 등록하고 인증한 주소로만 출금할 수 있게 제한해, 계정이 탈취돼도 공격자 주소로 자산이 빠져나가지 못하게 하는 기능입니다.","wallets-security",1],["copy-trading","카피 트레이딩(Copy trading)","카피 트레이딩은 다른 트레이더(리드 트레이더)의 매매를 내 계정에서 정해진 비율이나 금액으로 자동으로 따라 하는 거래소 기능입니다.","exchange-features",1],["candlestick-chart","캔들차트(Candlestick Chart)","캔들차트는 정해진 시간 동안의 시가, 고가, 저가, 종가를 막대 하나로 표시해 가격 움직임을 한눈에 보여 주는 차트입니다.","trading",1],["coin-margined-futures","코인 마진 선물(Coin-Margined Futures)","코인 마진 선물은 USDT가 아니라 BTC나 ETH 같은 코인 자체를 증거금으로 맡기고 손익도 그 코인으로 정산하는 선물로, 인버스 선물이라고도 부릅니다.","derivatives",1],["options","코인 옵션(Crypto Options)","코인 옵션은 정해진 만기일에 미리 정한 가격(행사가)으로 코인을 사거나 팔 수 있는 권리를 사고파는 파생상품으로, 사는 권리는 콜옵션, 파는 권리는 풋옵션이라고 합니다.","derivatives",1],["coin-vs-token","코인과 토큰의 차이(Coin vs Token)","코인은 자체 블록체인의 기본 자산(예: BTC, ETH)이고, 토큰은 다른 블록체인 위에서 스마트 컨트랙트로 발행된 자산(예: 이더리움 위의 USDT)입니다.","basics",1],["cold-wallet","콜드월렛(Cold Wallet, 콜드 스토리지)","콜드월렛은 개인 키를 인터넷과 분리된 환경에 보관해 온라인 해킹 위험을 크게 줄인 암호화폐 보관 방식입니다.","wallets-security",1],["cross-chain-bridge","크로스체인 브리지(Cross-chain Bridge)","크로스체인 브리지는 한 블록체인의 자산을 다른 블록체인에서 쓸 수 있도록 옮겨 주는 서비스로, 보통 원래 체인에 자산을 잠그고 다른 체인에서 같은 양을 발행합니다.","defi",1],["dex","탈중앙화 거래소(DEX)","탈중앙화 거래소(DEX)는 회사가 자산을 보관하지 않고 사용자가 개인 지갑에서 스마트 컨트랙트와 직접 토큰을 교환하는 거래소입니다.","defi",1],["tokenomics","토크노믹스(Tokenomics)","토크노믹스는 토큰의 총발행량, 배분 비율, 언락 일정, 사용처, 소각과 인플레이션 규칙 등 토큰의 공급과 수요를 결정하는 경제 구조 전체를 말합니다.","basics",1],["token-listing","토큰 상장(Token listing)","토큰 상장은 거래소가 심사를 거쳐 새로운 코인이나 토큰의 입금, 거래 페어, 출금을 열어 사용자가 사고팔 수 있게 하는 것입니다.","exchange-features",1],["token-burn","토큰 소각(Token Burn)","토큰 소각은 누구도 꺼낼 수 없는 주소로 토큰을 보내거나 컨트랙트에서 제거해 공급량을 영구적으로 줄이는 것입니다.","basics",1],["token-approval","토큰 승인(Token Approval, 허용량)","토큰 승인은 스마트 컨트랙트가 내 지갑의 특정 토큰을 정해진 한도만큼 대신 옮길 수 있도록 허락하는 서명으로, 한 번 주면 취소하기 전까지 유지됩니다.","wallets-security",1],["token-unlock","토큰 언락(Token Unlock)","토큰 언락은 팀, 투자자, 생태계 기금 등에게 배분된 뒤 잠겨 있던 토큰이 정해진 일정에 따라 풀려 거래 가능한 상태가 되는 것입니다.","basics",1],["tokenized-treasuries","토큰화 국채(Tokenized treasuries)","토큰화 국채는 미국 단기 국채나 이를 담은 머니마켓 펀드의 지분을 토큰으로 발행해, 블록체인에서 보유하고 이전하며 국채 이자를 받을 수 있게 한 상품입니다.","tokenized-assets",1],["tokenized-stocks","토큰화 주식(Tokenized stocks)","토큰화 주식은 실제 주식이나 그 가격을 따라가는 권리를 블록체인 토큰으로 발행해 암호화폐처럼 지갑과 거래소에서 거래할 수 있게 만든 자산입니다.","tokenized-assets",1],["unified-trading-account","통합 거래 계정(UTA)","통합 거래 계정은 현물, 선물, 옵션 거래를 하나의 계정 잔고와 증거금으로 함께 운용할 수 있게 묶은 거래소 계정 방식입니다.","exchange-features",1],["travel-rule","트래블룰(Travel rule)","트래블룰은 가상자산을 다른 사업자에게 보낼 때 보내는 사람과 받는 사람의 정보를 함께 전달하도록 요구하는 자금세탁방지 규칙입니다.","regulation",1],["transaction-hash","트랜잭션 해시(TxID)","트랜잭션 해시(TxID)는 블록체인에 기록된 거래 하나하나에 붙는 고유한 식별 문자열로, 송금이 실제로 처리됐는지 추적할 때 사용합니다.","wallets-security",1],["trailing-stop","트레일링 스탑(Trailing Stop)","트레일링 스탑은 가격이 유리하게 움직이면 손절 가격이 일정 간격을 유지하며 함께 따라 올라가고, 가격이 그 간격만큼 되돌리면 포지션을 정리하는 주문입니다.","trading",1],["fud","퍼드(FUD)","퍼드(FUD)는 Fear, Uncertainty, Doubt의 약자로, 공포와 불확실성, 의심을 퍼뜨려 시장 참여자의 매도를 부추기는 정보나 분위기를 말합니다.","basics",1],["funding-rate-arbitrage","펀딩비 차익거래(Funding Rate Arbitrage)","펀딩비 차익거래는 현물을 사고 같은 양의 무기한 선물을 숏으로 잡아 가격 방향 위험을 상쇄한 채, 숏 포지션이 받는 펀딩비를 수익으로 얻는 전략입니다.","derivatives",1],["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다.","derivatives",1],["fomo","포모(FOMO)","포모(FOMO)는 Fear Of Missing Out의 약자로, 남들이 다 버는 기회를 나만 놓칠까 봐 불안해서 충분한 판단 없이 급하게 매수하는 심리를 말합니다.","basics",1],["post-only-order","포스트 온리 주문(Post-Only)","포스트 온리 주문은 반드시 호가창에 대기 주문으로 올라가는 지정가 주문으로, 즉시 체결될 상황이면 자동으로 취소되어 항상 메이커로만 체결되게 합니다.","trading",1],["position-sizing","포지션 사이징(Position Sizing)","포지션 사이징은 한 번의 거래에서 잃어도 되는 금액을 먼저 정하고, 손절 거리에 맞춰 진입할 수량을 계산하는 자금 관리 방법입니다.","trading",1],["portfolio-margin","포트폴리오 마진(Portfolio Margin)","포트폴리오 마진은 개별 포지션이 아니라 계좌 전체 포지션의 순위험을 계산해 필요한 증거금을 정하는 방식으로, 서로 상쇄되는 포지션이 많을수록 증거금 부담이 줄어듭니다.","derivatives",1],["flash-loan","플래시 론(Flash Loan)","플래시 론은 담보 없이 큰 금액을 빌리되 같은 블록체인 거래 안에서 바로 갚아야 하는 대출로, 갚지 못하면 거래 전체가 취소됩니다.","defi",1],["anti-phishing-code","피싱 방지 코드(Anti-phishing Code)","피싱 방지 코드는 사용자가 직접 정한 문구를 거래소가 공식 이메일에 함께 표시해, 그 문구가 없는 메일은 가짜임을 쉽게 알아보게 하는 보안 기능입니다.","wallets-security",1],["phishing","피싱(Phishing)","피싱은 가짜 웹사이트, 메일, 메시지, 광고로 공식 서비스인 척 접근해 비밀번호, 시드 문구, 지갑 서명을 빼내는 사기 수법입니다.","wallets-security",1],["hardware-wallet","하드웨어 지갑(Hardware Wallet)","하드웨어 지갑은 개인 키를 전용 보안 기기 안에 보관하고 거래 서명도 기기 안에서 처리해 키가 컴퓨터나 휴대폰에 노출되지 않게 하는 지갑입니다.","wallets-security",1],["bear-market","하락장(Bear Market, 베어장)","하락장은 가격이 비교적 긴 기간 동안 전반적으로 내려가고 투자 심리가 비관적인 시장 국면으로, 베어장 또는 약세장이라고도 부릅니다.","basics",1],["synthetic-dollar","합성 달러(델타 중립 스테이블코인)","합성 달러는 현물 암호화폐를 보유하면서 같은 규모의 선물 숏 포지션으로 가격 변동을 상쇄해 1달러 가치를 만드는 델타 중립형 스테이블코인입니다.","stablecoins",1],["hot-wallet","핫월렛(Hot Wallet)","핫월렛은 인터넷에 연결된 기기에서 개인 키를 관리해 바로 송금과 서명을 할 수 있는 온라인 상태의 암호화폐 지갑입니다.","wallets-security",1],["hash-rate","해시레이트(Hash rate)","해시레이트는 작업증명 블록체인에서 채굴 장비들이 1초에 계산하는 해시의 총량으로, 네트워크의 채굴 경쟁 강도와 보안 수준을 보여 주는 지표입니다.","onchain",1],["hedging","헤지(Hedging)","헤지는 이미 가진 포지션의 가격 변동 위험을 줄이기 위해 반대 방향으로 움직이는 포지션을 함께 잡는 위험 관리 방법입니다.","derivatives",1],["spot-trading","현물 거래(Spot Trading)","현물 거래는 코인을 현재 가격에 실제로 사고팔아 즉시 소유권이 넘어가는 거래 방식으로, 산 코인은 바로 내 계정 잔고에 들어옵니다.","trading",1],["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다.","trading",1],["hodl","호들(HODL)","호들(HODL)은 단기 가격 변동에 흔들리지 않고 암호화폐를 오래 보유하는 전략이나 태도를 뜻하는 코인 커뮤니티 용어입니다.","basics",1],["active-addresses","활성 주소(Active addresses)","활성 주소는 일정 기간 안에 거래를 보내거나 받은 고유 지갑 주소의 수로, 블록체인 네트워크가 실제로 얼마나 쓰이는지를 보여 주는 지표입니다.","onchain",1],["aml","AML(자금세탁방지)","AML은 범죄 수익이 합법 자금처럼 세탁되는 것을 막기 위해 금융기관과 거래소가 지켜야 하는 감시·보고 규정과 절차를 말합니다.","regulation",1],["apr-vs-apy","APR과 APY의 차이","APR은 복리를 반영하지 않은 단순 연이율이고, APY는 받은 이자를 다시 굴리는 복리 효과까지 반영한 연 수익률입니다.","defi",1],["cbdc","CBDC(중앙은행 디지털화폐)","CBDC는 중앙은행이 직접 발행하고 책임지는 디지털 형태의 법정화폐로, 현금과 같은 법적 지위를 갖도록 설계된 돈입니다.","stablecoins",1],["dao","DAO(탈중앙화 자율 조직)","DAO(탈중앙화 자율 조직)는 경영진 대신 토큰 보유자의 투표와 스마트 컨트랙트 규칙으로 자금 사용과 주요 결정을 내리는 온라인 조직입니다.","defi",1],["kyc","KYC(고객확인제도)","KYC는 거래소 같은 금융 서비스가 고객의 신원을 확인하고 기록하는 절차로, 자금세탁 방지 규정에 따라 계정 개설이나 입출금 전에 요구됩니다.","regulation",1],["mev","MEV(최대 추출 가능 가치)","MEV는 블록 생성자나 봇이 블록 안 거래의 순서를 정하거나 끼워 넣어 얻을 수 있는 추가 이익을 말하며, 샌드위치 공격이 대표적인 예입니다.","defi",1],["mica","MiCA(EU 가상자산시장법)","MiCA는 유럽연합이 만든 가상자산 시장 규정으로, 스테이블코인 발행사와 가상자산 서비스 제공자(CASP)에 대한 인가와 운영 기준을 EU 전체에 통일했습니다.","regulation",1],["nft","NFT(대체 불가능 토큰)","NFT(대체 불가능 토큰)는 각각 고유한 ID를 가져 서로 바꿔 쓸 수 없는 블록체인 토큰으로, 디지털 그림, 게임 아이템, 멤버십 같은 소유 기록에 쓰입니다.","defi",1],["oco-order","OCO 주문(One-Cancels-the-Other)","OCO 주문은 두 개의 주문을 묶어 하나가 체결되면 나머지 하나가 자동으로 취소되도록 하는 주문 방식으로, 익절과 손절을 동시에 걸 때 주로 씁니다.","trading",1],["p2p-trading","P2P 거래(C2C)","P2P 거래는 거래소가 중개하는 게시판에서 개인끼리 은행 이체 등 법정화폐로 대금을 주고받고 USDT 같은 코인을 사고파는 방식입니다.","exchange-features",1],["total-value-locked","TVL(총 예치 자산)","TVL(총 예치 자산)은 특정 디파이 프로토콜이나 블록체인의 스마트 컨트랙트에 예치된 자산을 현재 가격으로 환산한 총액입니다.","defi",1],["usdc","USDC(USD 코인)","USDC는 미국 기업 서클(Circle)이 발행하는 미국 달러 연동 스테이블코인으로, 현금과 단기 미국 국채 등 준비자산으로 1대1 가치를 뒷받침합니다.","stablecoins",1],["usdt-margined-futures","USDT 마진 선물(USDT-Margined Futures)","USDT 마진 선물은 USDT를 증거금으로 맡기고 손익도 USDT로 정산하는 선물로, 가격 변동과 손익이 정비례하는 리니어 구조라서 계산이 직관적입니다.","derivatives",1],["usdt","USDT(테더)","USDT(테더)는 테더(Tether)사가 발행하는 미국 달러 연동 스테이블코인으로, 거래량과 시가총액 기준 가장 큰 스테이블코인입니다.","stablecoins",1],["vasp","VASP(가상자산사업자)","VASP는 가상자산의 매매, 교환, 이전, 보관 같은 서비스를 다른 사람을 위해 제공하는 사업자로, 거래소와 수탁 지갑 업체가 대표적입니다.","regulation",1],["vip-tier","VIP 수수료 등급","VIP 수수료 등급은 거래소가 최근 거래량이나 보유 자산 규모에 따라 사용자를 단계별로 나누고 높은 등급일수록 낮은 메이커·테이커 수수료를 적용하는 제도입니다.","exchange-features",1]]});
